mapper.select:
SELECT FROM emp07_career JOIN emp01_person ON emp07_person_id = emp01_person_id WHERE emp01_company_id = #{companyId} AND emp07_person_id = #{personId}
AND coalesce(emp07_extr_add_title_yn,'false') = 'true'
ORDER BY emp07_fr_ym DESC

mapper.insert:
INSERT INTO emp07_career
       ( emp07_career_id, emp07_person_id, emp07_fr_ym, emp07_to_ym
       , emp07_company_nm, emp07_industry, emp07_final_org, emp07_final_title
       , emp07_career_ty_cd, emp07_final_role
       , emp07_finance_relate_yn, emp07_main_career_yn, emp07_extr_add_title_yn
       , emp07_note )
VALUES ( #{careerId}, #{req.personId}, #{req.frYm}, #{req.toYm}
       , #{req.companyNm}, #{req.industry}, #{req.finalOrg}, #{req.finalTitle}
       , #{req.careerTyCd}, #{req.finalRole}
       , #{req.financeRelateYn}, #{req.mainCareerYn}, #{req.extrAddTitleYn}
       , #{req.note} )

mapper.update:
UPDATE emp07_career
   SET emp07_fr_ym            = #{req.frYm}
     , emp07_to_ym            = #{req.toYm}
     , emp07_company_nm       = #{req.companyNm}
     , emp07_industry         = #{req.industry}
     , emp07_final_org        = #{req.finalOrg}
     , emp07_final_title      = #{req.finalTitle}
     , emp07_career_ty_cd     = #{req.careerTyCd}
     , emp07_final_role       = #{req.finalRole}
     , emp07_finance_relate_yn = #{req.financeRelateYn}
     , emp07_main_career_yn   = #{req.mainCareerYn}
     , emp07_extr_add_title_yn = #{req.extrAddTitleYn}
     , emp07_note             = #{req.note}
 WHERE emp07_career_id = #{careerId}
   AND emp07_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

